const response = $json.choices[0].message.content;

const strategy = JSON.parse(response);

return [
  {
    json: {
      analysis_request_id: $('Fetch AI Analysis').first().json.analysis_request_id,

      overall_opportunity_score: strategy.overall_opportunity_score,
      priority_recommendations: strategy.priority_recommendations,
      recommended_next_steps: strategy.recommended_next_steps,
      product_improvements: strategy.product_improvements,
      business_strategy: strategy.business_strategy,
      go_to_market_strategy: strategy.go_to_market_strategy,
      recommendation_summary: strategy.recommendation_summary,
      analysis_status: strategy.analysis_status,
      confidence_score: strategy.confidence_score,
      updated_at: strategy.updated_at
    }
  }
];
